/**
 * The generated `$flamme/auto-routes` shim (REQ-3).
 *
 * `createFlammeRouter()` must read the generated route table without `@flamme/router` depending on a
 * file that does not exist when the package is compiled. The plugin writes **this** module next to
 * the generated tree and `@flamme/router/auto` imports it by its `$flamme` specifier, so:
 *
 * - the router package has no build-time import of the generated module (nothing to resolve at
 *   package-build time, and the published `dist/auto.js` is complete on its own);
 * - a runtime that never creates a router never asks for the generated module: the import happens
 *   inside `createFlammeRouter()`, so a plain Node test or a dev server that cannot resolve
 *   `$flamme/auto-routes` gets the actionable `FLM4011` message instead of a resolution crash at
 *   module load;
 * - the shim installs the **flat** `records` export, not the nested default. `composeFlammeRoutes`
 *   reads `parent` links off the flat table, and the nested table has already dropped the loader
 *   definitions `defineFlammeRoutes` materialises with a client, so a `RouteRecordRaw` tree is not
 *   a table `createFlammeRouter()` can compose or install.
 *
 * The shim itself is three lines; `emitRoutesShim` renders it so the plugin and the tests share one
 * spelling of the import.
 */

/** The `$flamme` specifier of the generated route module. */
export const GENERATED_ROUTES_SPECIFIER = '$flamme/routes';

/** The `$flamme` specifier of the generated shim module. */
export const GENERATED_SHIM_SPECIFIER = '$flamme/auto-routes';

/**
 * Renders the shim: the module `@flamme/router/auto` imports.
 *
 * ```ts
 * import { setGeneratedRoutes } from '@flamme/router/auto'
 * import { records } from '$flamme/routes'
 * setGeneratedRoutes(records)
 * ```
 */
export function emitRoutesShim(): string {
  return [
    '// GENERATED by @flamme/vite — do not edit.',
    '//',
    '// Installs the generated route table into @flamme/router/auto. `createFlammeRouter()` imports',
    '// this module dynamically; a build without a generated tree never loads it.',
    '',
    "import { setGeneratedRoutes } from '@flamme/router/auto'",
    `import { records } from '${GENERATED_ROUTES_SPECIFIER}'`,
    '',
    'setGeneratedRoutes(records)',
    '',
  ].join('\n');
}
